<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/audit.php'; require_once __DIR__ . '/../includes/notifications.php'; requireRole('doctor');
$doctorQuery = $pdo->prepare('SELECT d.id, u.hospital_id FROM doctors d JOIN users u ON u.id = d.user_id WHERE u.id = :user_id LIMIT 1'); $doctorQuery->execute([':user_id' => $_SESSION['user_id']]); $doctor = $doctorQuery->fetch(PDO::FETCH_ASSOC); $doctorId = $doctor['id'] ?? null; $hospitalId = $doctor['hospital_id'] ?? null;
if (!$doctorId) { http_response_code(403); exit('Doctor profile not found.'); }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $patientId = filter_input(INPUT_POST, 'patient_id', FILTER_VALIDATE_INT); $type = trim($_POST['record_type'] ?? ''); $title = trim($_POST['record_title'] ?? ''); $description = trim($_POST['record_description'] ?? ''); if (!verifyCsrfToken($_POST['csrf_token'] ?? null) || !$patientId || !$hospitalId || $type === '' || $title === '' || $description === '') { flash('danger', 'Complete all medical record fields.'); } else { $insert = $pdo->prepare('INSERT INTO medical_records (patient_id, doctor_id, hospital_id, record_type, record_title, record_description) VALUES (:patient_id, :doctor_id, :hospital_id, :type, :title, :description)'); $insert->execute([':patient_id' => $patientId, ':doctor_id' => $doctorId, ':hospital_id' => $hospitalId, ':type' => $type, ':title' => $title, ':description' => $description]); $recordId = (int) $pdo->lastInsertId(); $patientUserQuery = $pdo->prepare('SELECT user_id FROM patients WHERE id = :patient_id LIMIT 1'); $patientUserQuery->execute([':patient_id' => $patientId]); $patientUserId = (int) $patientUserQuery->fetchColumn(); if ($patientUserId) { createNotification($pdo, $patientUserId, 'Medical record created', 'A new medical record is available in your patient portal.'); } logAudit('MEDICAL_RECORD_CREATED', 'medical_record', $recordId, 'Medical record created by doctor.'); flash('success', 'Medical record created.'); redirect('medical_records.php'); } }
$patients = $pdo->query("SELECT p.id, i.full_name, i.demo_health_id FROM patients p JOIN demo_health_identities i ON i.id = p.health_identity_id WHERE i.verification_status = 'verified' ORDER BY i.full_name")->fetchAll(PDO::FETCH_ASSOC); $recordsQuery = $pdo->prepare('SELECT m.record_title, m.record_type, m.record_description, m.created_at, i.full_name FROM medical_records m JOIN patients p ON p.id = m.patient_id JOIN demo_health_identities i ON i.id = p.health_identity_id WHERE m.doctor_id = :doctor_id ORDER BY m.created_at DESC'); $recordsQuery->execute([':doctor_id' => $doctorId]); $records = $recordsQuery->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'Medical Records'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">Clinical documentation</p><h1 class="h2">Medical Records</h1></div></div><div class="row g-4"><div class="col-lg-5"><div class="setup-card"><h2 class="h5">Create record</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><label class="form-label">Patient</label><select class="form-select mb-3" name="patient_id" required><option value="">Select patient</option><?php foreach ($patients as $patient): ?><option value="<?= (int) $patient['id'] ?>"><?= e($patient['full_name'] . ' - ' . $patient['demo_health_id']) ?></option><?php endforeach; ?></select><label class="form-label">Record type</label><input class="form-control mb-3" name="record_type" placeholder="Clinical note" required><label class="form-label">Record title</label><input class="form-control mb-3" name="record_title" required><label class="form-label">Description</label><textarea class="form-control mb-3" name="record_description" rows="5" required></textarea><button class="btn btn-primary">Create medical record</button></form></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Records created by you</h2><?php foreach ($records as $record): ?><article class="border-bottom py-3"><h3 class="h6 mb-1"><?= e($record['record_title']) ?></h3><div class="small text-muted"><?= e($record['full_name']) ?> | <?= e($record['record_type']) ?> | <?= e($record['created_at']) ?></div><p class="mb-0 mt-2"><?= e($record['record_description']) ?></p></article><?php endforeach; ?><?php if (!$records): ?><p class="text-muted mb-0">No records created yet.</p><?php endif; ?></div></div></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>